cache = {}

for path, payload in new_files.items():
    target = Path(path)

    if target.exists():
        raise SystemExit(
            f"Refusing to overwrite existing file: {path}"
        )

    target.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    target.write_text(
        base64.b64decode(
            payload
        ).decode("utf-8"),
        encoding="utf-8",
    )

    print("✓ created", path)

for path, old_b64, new_b64, label in mods:
    target = Path(path)

    if not target.exists():
        raise SystemExit(
            f"Missing {path}"
        )

    text = cache.get(
        path,
        target.read_text(
            encoding="utf-8",
        ),
    )

    old = base64.b64decode(
        old_b64
    ).decode("utf-8")

    new = base64.b64decode(
        new_b64
    ).decode("utf-8")

    count = text.count(old)

    if count != 1:
        raise SystemExit(
            f"{label}: expected 1 match, found {count}."
        )

    cache[path] = text.replace(
        old,
        new,
        1,
    )

for path, text in cache.items():
    Path(path).write_text(
        text,
        encoding="utf-8",
    )
    print("✓", path)

